       s.currency,
       s.interval_months,
       s.is_active,
       s.created_at,
       s.updated_at
FROM pettycashv2.billing_plan s
WHERE ((s.currency) IS NULL OR EXISTS (SELECT 1 FROM pettycash_test.currency_info _p WHERE _p.currency_code = (s.currency)));

INSERT INTO pettycash_test.billing_policy
  (id,
   trial_days,
